import React, { useState } from 'react';
import { Alert, Box, Card, CardContent, Chip, Grid, Stack, Typography, useTheme } from '@mui/material';
import VOICE_COMMANDS from '../../data/voiceCommands';

// Full Muslim Companion voice-command reference (all intents of the live skill).
// Data: src/data/voiceCommands.js, generated from the API repo's
// src/data/voiceCommands.json by scripts/buildVoiceCommands.mjs, which checks
// every phrase against the interaction model. Commands in a release Amazon is
// not available yet carry `comingSoon` (and optionally `soonNote`, the reason) and show a badge (2026-10-02; release live 2026-10-07).

export default function VoiceCommandReference() {
    const theme = useTheme();
    const [group, setGroup] = useState('all');
    // Arabic / Hindi phrases come from the ar-SA / hi-IN voice models (live since 2026-10-07).
    const languages = VOICE_COMMANDS.languages || {};
    const [lang, setLang] = useState('en');
    const L = lang === 'en' ? null : languages[lang];
    const phrasesFor = (cmd) => (L ? (L.say[cmd.say[0]] || []) : cmd.say);
    const groups = VOICE_COMMANDS.categories;
    const shown = group === 'all' ? groups : groups.filter((g) => g.id === group);

    const comingSoonCount = groups.reduce((n, g) => n + g.commands.filter((c) => c.comingSoon).length, 0);

    return (
        <Box>
            <Alert severity="info" variant="outlined" sx={{ mb: 3, borderRadius: 2 }}>
                <Typography variant="subtitle2" fontWeight={700}>Languages and countries</Typography>
                <Typography variant="body2">
                    Muslim Companion understands <b>English</b>, <b>Arabic</b> (“الرفيق المسلم”) and <b>Hindi</b> (“मुस्लिम कम्पैनियन”).
                    In English, say the phrases exactly as written, starting with “Alexa, ask Muslim Companion…” (the name is the same in
                    the <b>United States, Canada, the United Kingdom, India and Australia</b>). Choose a language above to see the Arabic or Hindi phrases.
                    Where a phrase has a choice, such as a calculation method, the description lists every option you can say.
                </Typography>
                {comingSoonCount > 0 && (
                    <Typography variant="body2" sx={{ mt: 0.75 }}>
                        Commands marked <b>Coming soon</b> are not available yet; the badge says why.
                    </Typography>
                )}
            </Alert>
            {Object.keys(languages).length > 0 && (
                <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" justifyContent="center" sx={{ mb: 2 }}>
                    <Chip label="English" onClick={() => setLang('en')} color={lang === 'en' ? 'secondary' : 'default'} variant={lang === 'en' ? 'filled' : 'outlined'} />
                    {Object.entries(languages).map(([code, l]) => (
                        <Chip key={code} label={`${l.title}${l.comingSoon ? ' · coming soon' : ''}`} onClick={() => setLang(code)} color={lang === code ? 'secondary' : 'default'} variant={lang === code ? 'filled' : 'outlined'} />
                    ))}
                </Stack>
            )}
            {L && (
                <Alert severity="info" variant="outlined" sx={{ mb: 3, borderRadius: 2 }}>
                    <Typography variant="body2">
                        <b>{L.title}</b>: set your Alexa language to {lang === 'ar' ? 'Arabic (Saudi Arabia)' : 'Hindi (India)'} to use Muslim Companion in {L.title}.
                        The skill’s name in this language is <b dir={L.dir}>{L.invocation}</b>. These are the exact phrases it understands; the descriptions stay in English.
                    </Typography>
                </Alert>
            )}
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" justifyContent="center" sx={{ mb: 4 }}>
                <Chip label="All" onClick={() => setGroup('all')} color={group === 'all' ? 'primary' : 'default'} variant={group === 'all' ? 'filled' : 'outlined'} />
                {groups.map((g) => (
                    <Chip key={g.id} label={g.title} onClick={() => setGroup(g.id)} color={group === g.id ? 'primary' : 'default'} variant={group === g.id ? 'filled' : 'outlined'} />
                ))}
            </Stack>

            {shown.map((g) => (
                <Box key={g.id} sx={{ mb: 5 }}>
                    <Typography variant="h5" component="h3" sx={{ mb: 2, fontWeight: 600 }}>{g.title}</Typography>
                    <Grid container spacing={2.5}>
                        {[...g.commands].sort((a, b) => Number(Boolean(a.comingSoon)) - Number(Boolean(b.comingSoon))).map((cmd) => (
                            <Grid item xs={12} sm={6} md={4} key={cmd.say[0]}>
                                <Card elevation={1} sx={{ height: '100%', borderRadius: 2, ...(cmd.comingSoon ? { opacity: 0.8, borderStyle: 'dashed', borderWidth: 1, borderColor: 'warning.light' } : {}) }}>
                                    <CardContent>
                                        {phrasesFor(cmd).map((s) => (
                                            <Typography key={s} variant="subtitle1" fontWeight={600} dir={L ? L.dir : 'ltr'} sx={{ lineHeight: 1.35, mb: 0.75, textAlign: L?.dir === 'rtl' ? 'right' : 'left' }}>
                                                <Box component="span" sx={{ color: theme.palette.primary.main }}>“</Box>{s}<Box component="span" sx={{ color: theme.palette.primary.main }}>”</Box>
                                            </Typography>
                                        ))}
                                        <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>{cmd.does}</Typography>
                                        <Stack direction="row" spacing={0.75} useFlexGap flexWrap="wrap" sx={{ mt: 1.25 }}>
                                            {(cmd.comingSoon || L?.comingSoon) && <Chip size="small" color="warning" label={cmd.soonNote || 'Coming soon'} />}
                                            {cmd.screen && <Chip size="small" label="Shows on Echo Show" />}
                                            {!cmd.say.some((x) => /Muslim Companion/i.test(x)) && <Chip size="small" variant="outlined" label="While Muslim Companion is playing" />}
                                            {cmd.caution && <Chip size="small" color="warning" variant="outlined" label="Turns the automatic Athan off" />}
                                        </Stack>
                                    </CardContent>
                                </Card>
                            </Grid>
                        ))}
                    </Grid>
                    {g.tip && <Typography variant="body2" color="text.secondary" sx={{ mt: 1.5 }}>Tip: {g.tip}</Typography>}
                </Box>
            ))}

            <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 2 }}>
                You can also start with “Alexa, open Muslim Companion” and then ask. Commands like “next”, “pause” and “stop” work while Muslim Companion is playing.
            </Typography>
        </Box>
    );
}
